\section{Common notation and results}\label{sec:results}\label{h:sec:mainresults}
Let $X,X_1,X_2,\ldots$ be iid real random variables with
$\E X=0$ and $0<\sigma^2=\E X^2<\infty$. For $n\ge1$, put
\begin{equation}\label{h:eq:statistics}
 S_k=S_k^X=\sum_{i=1}^kX_i,\quad Q_k=\sum_{i=1}^kX_i^2,\quad
 V_n=\sqrt{Q_n},\quad S_0=Q_0=0,
\end{equation}

The compact part holds without \eqref{h:eq:assumptions} and also
retains the endpoint. This is a separate finite-variance assertion.

\begin{theorem}[Compact maximum and endpoint comparison]\label{c:main}
Assume only $\E X=0$ and $0<\E X^2=\sigma^2<\infty$. Then
\begin{align}
 \sup_{0\le x\le1}
 |\PP(M\ge x\sqrt Q)-\PP(M_B\ge x)|&\le CR,\label{cn:CP}\\
 \sup_{\substack{0\le x\le1\\v\in\R}}
 |\PP(M<x\sqrt Q,W\le v)-\PP(M_B<x,B_1\le v)|&\le CR.
 \label{cn:JT}
\end{align}
The same joint estimate holds for the weak crossing complements.
No continuity, symmetry, density or nonlattice condition is imposed.
\end{theorem}

\subsection{Rare marked cubic and unmarked-future budgets}
\begin{lemma}[Rare real-suffix budgets]\label{d:rare}
In \eqref{d:resregime}, choose $K$ once for the finitely many fixed
drift and inverse powers used below. For each such $p\ge0$,
\begin{align}\label{d:raregrids}
 \sum_{t\ge n/2}E[1_{\{T_t\ge h_0\}}|X_1|^3T_t^{-3/2}D_t^p;
                         |d_t|\ge3x\sqrt{T_t}/2]
 &\le C_p\delta\{\Psi(3x/2)^{1/2}+e^{-x^2}\},\nonumber\\
 \frac1n\sum_{t\le n/2}E[1_{\{T_t\ge h_0\}}|X_1|^3T_t^{-1/2}D_t^p;
                         |d_t|\ge3x\sqrt{T_t}/2]
 &\le C_p\delta\Psi(x).
\end{align}
For $t\ge m$, $U=\sum_{i=1}^tX_i^2$, $d'=\sum_{i=1}^tX_i$,
$v_x=\sqrt{9x^2/4-1}$, one also has
\begin{equation}\label{d:FUT}
 E[1_{\{U\ge H/2\}}U^{-1/2}(1+|d'|/\sqrt U)^2;
                          |d'|\ge v_x\sqrt U]
 \le Ct^{-1/2}\Psi(x).
\end{equation}
\end{lemma}
\begin{proof}
Write $A_x=\Psi(3x/2)^{1/2}+e^{-x^2}$ and
$\phi(s)=Ee^{-sX^2}$. The common pointwise assertions, for $m\le t\le n$
and the fixed $q>0,p\ge0$ required here, are
\begin{align}\label{d:raremoments}
 E[1_{\{T_t\ge h_0\}}|X_1|^3T_t^{-q/2}D_t^p;
                      |d_t|\ge3x\sqrt{T_t}/2]
 &\le C_{p,q}\beta t^{-q/2}A_x,\nonumber\\
 E[1_{\{T_t\ge h_0\}}T_t^{-q/2}D_t^p;
                      |d_t|\ge v_x\sqrt{T_t}]
 &\le C_{p,q}t^{-q/2}A_x.
\end{align}
We prove them with the same deterministic length cutoff $m$ as in
the terminal estimate; all laws in this proof are bounded product
laws at deterministic original iid ranks.

Use the common signed moments and incomplete-gamma inequality proved
with \eqref{cnx:dampedbudget}, specialized in Lemma~\ref{d:damped},
decreasing $c$ once for
the finite list of powers. Its short grid in \eqref{d:grids}, with
the arbitrary upper limit denoted by $M$, gives
\begin{equation}\label{d:rareshort}
 \frac1n\sum_{t\le M}E[1_{\{T_t\ge h_0\}}|X_1|^3T_t^{-1/2}D_t^p]
 \le C_p\beta\sqrt M/n.
\end{equation}
That printed proof sums $C\min(M,s^{-1})$ against $s^{-1/2}$;
it includes $t=1$, with every quotient masked by actual energy.

Fix $L$ large after $c$. For $t\ge m$, $l=t$ or $t-1$, and
$st\le Lx^2$, tilt by $dP_s=e^{-sX^2}dP/\phi(s)$.
Jensen gives $\phi(s)\ge e^{-s}$, and $EX=0$ gives
\[
 |\mu_s|=|E_sX|\le e^ss\beta\le2s\beta,\quad
 s\beta^2\le\frac{Lx^2}{K(1+x)^6},\quad
 \sqrt l|\mu_s|\le\frac{2L\beta x^2}{\sqrt t}
                   \le\frac{2L}{\sqrt K(1+x)}.
\]
Increase $K$ so $s\le1/(128\beta^2)$ and $\beta\sqrt s\le.01$.
